import type { Metadata } from "next";
import type { Resort } from "@/types/resort";

export const SITE_NAME = "Ontario Ski Guide";
export const SITE_TITLE =
  "Ontario Ski Guide – Ski Resorts, Lift Tickets & Conditions";
export const SITE_TAGLINE = "Ski resorts, lift ticket prices & snow conditions";
export const SITE_DESCRIPTION =
  "Compare ski resorts and hills in Ontario and across Canada: lift ticket prices, ski and snowboard rentals, trail maps, hours, snow conditions and directions.";
// Route generated by src/app/opengraph-image.tsx; used when a page has no image of its own.
export const DEFAULT_OG_IMAGE = "/opengraph-image";

export function getSiteUrl() {
  if (process.env.NEXT_PUBLIC_SITE_URL) return process.env.NEXT_PUBLIC_SITE_URL;
  if (process.env.VERCEL_PROJECT_PRODUCTION_URL) {
    return `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`;
  }
  return "http://localhost:3000";
}

// Child pages that define `openGraph` replace the root block entirely, so they
// spread this to keep site-wide fields.
export const baseOpenGraph = {
  siteName: SITE_NAME,
  locale: "en_CA",
} satisfies Metadata["openGraph"];

export function resortTitle(resort: Resort) {
  return /\b(ski|resort|hill|club)\b/i.test(resort.name)
    ? resort.name
    : `${resort.name} Ski Resort`;
}

export function resortDescription(resort: Resort) {
  const place = [resort.region, resort.country].filter(Boolean).join(", ");
  const prices = [
    resort.dayTicketPrice > 0 && `lift tickets from $${resort.dayTicketPrice}`,
    resort.skiRentalPrice > 0 && `ski rental $${resort.skiRentalPrice}`,
    resort.snowBoardRentalPrice > 0 &&
      `snowboard rental $${resort.snowBoardRentalPrice}`,
  ].filter(Boolean);
  const runs: [number, string][] = [
    [resort.runs.green, "green"],
    [resort.runs.blue, "blue"],
    [resort.runs.black, "black"],
    [resort.runs.doubleBlack, "double black"],
  ];
  const openRuns = runs.filter(([count]) => count > 0);
  const totalRuns = openRuns.reduce((sum, [count]) => sum + count, 0);

  return [
    `${resort.name}${place ? ` (${place})` : ""}${prices.length ? `: ${prices.join(", ")}` : ""}.`,
    totalRuns > 0 &&
      `${totalRuns} ${totalRuns === 1 ? "run" : "runs"}: ${openRuns.map(([count, label]) => `${count} ${label}`).join(", ")}.`,
    "Trail map, hours, conditions and directions.",
  ]
    .filter(Boolean)
    .join(" ");
}
